","new":"  // Merge the alloc liverange with the liveranges of descriptors derived
  // transitively through views and selects. Either select operand may back
  // the result and must remain live through its uses.
  SmallVector<Operation *> users(value.getUsers());
  DenseSet<Operation *> seen;
  while (!users.empty()) {
    Operation *user = users.pop_back_val();
    if (!seen.insert(user).second)
      continue;
    if (!user->hasTrait<OpTrait::MemDescViewTrait>() &&
        !isa<arith::SelectOp>(user))
      continue;
